package com.franco.desco.adapter.in.web.census;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.census.port.in.CensusUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController@RequestMapping("/api/v1/censos")@Tag(name="Censos de plantas",description="Historial y registro de censos de plantas por cultivo.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class CensusController{private final CensusUseCase u;private final CensusWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public CensusController(CensusUseCase u,CensusWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}@GetMapping@PreAuthorize("@permissionGuard.has(authentication,'CENSOS_LISTAR')")@Operation(operationId="censosListar",summary="Listar historial de censos")public ResponseEntity<ApiResponse<PageResponse<CensusResponses.Summary>>>list(@RequestParam(required=false)Long parcelaCultivoId,@RequestParam(required=false)Long parcelaId,@RequestParam(required=false)LocalDate fechaDesde,@RequestParam(required=false)LocalDate fechaHasta,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,parcelaCultivoId,parcelaId,fechaDesde,fechaHasta),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}@PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'CENSOS_CREAR')")@Operation(operationId="censosCrear",summary="Registrar censo")public ResponseEntity<ApiResponse<CensusResponses.Created>>create(@Valid@RequestBody CensusRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(map.command(q),ids.resolve(a),meta.resolve(r)),r,CensusResponses.Created::new);}@PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'CENSOS_EDITAR')")@Operation(operationId="censosEditar",summary="Editar censo")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody CensusRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}}
